WITH promo_sales AS ( SELECT p.p_promo_sk, SUM(COALESCE(ss.ss_net_profit, 0) + COALESCE(ws.ws_net_profit, 0)) AS total_net_profit FROM promotion p LEFT JOIN store_sales ss ON ss.ss_promo_sk = p.p_promo_sk LEFT JOIN web_sales ws ON ws.ws_promo_sk = p.p_promo_sk GROUP BY p.p_promo_sk ), channel_sales AS ( SELECT 'Email' AS channel, ps.total_net_profit FROM promo_sales ps JOIN promotion p ON ps.p_promo_sk = p.p_promo_sk WHERE p.p_channel_email = 'Y' UNION ALL SELECT 'TV', ps.total_net_profit FROM promo_sales ps JOIN promotion p ON ps.p_promo_sk = p.p_promo_sk WHERE p.p_channel_tv = 'Y' UNION ALL SELECT 'Radio', ps.total_net_profit FROM promo_sales ps JOIN promotion p ON ps.p_promo_sk = p.p_promo_sk WHERE p.p_channel_radio = 'Y' UNION ALL SELECT 'Catalog', ps.total_net_profit FROM promo_sales ps JOIN promotion p ON ps.p_promo_sk = p.p_promo_sk WHERE p.p_channel_catalog = 'Y' UNION ALL SELECT 'DMail', ps.total_net_profit FROM promo_sales ps JOIN promotion p ON ps.p_promo_sk = p.p_promo_sk WHERE p.p_channel_dmail = 'Y' UNION ALL SELECT 'Press', ps.total_net_profit FROM promo_sales ps JOIN promotion p ON ps.p_promo_sk = p.p_promo_sk WHERE p.p_channel_press = 'Y' UNION ALL SELECT 'Event', ps.total_net_profit FROM promo_sales ps JOIN promotion p ON ps.p_promo_sk = p.p_promo_sk WHERE p.p_channel_event = 'Y' UNION ALL SELECT 'Demo', ps.total_net_profit FROM promo_sales ps JOIN promotion p ON ps.p_promo_sk = p.p_promo_sk WHERE p.p_channel_demo = 'Y' ) SELECT channel, SUM(total_net_profit) AS total_net_profit, DENSE_RANK() OVER (ORDER BY SUM(total_net_profit) DESC) AS channel_rank FROM channel_sales GROUP BY channel ORDER BY total_net_profit DESC LIMIT 10
